"""Verify PLE dev artifacts were generated by the current executable harness.

This is a cold, deterministic source-custody preflight. It does not inspect
hidden dev answers, run a model, mutate files or claim an organizer score.

Exit 0: every required runtime input's exact Git blob hash matches provenance.
Exit 3: stale/missing/unsafe artifacts, never quietly treat an inherited score
        as the new harness's score.
Exit 2: malformed input or inaccessible source.
"""
from __future__ import annotations

import argparse
import hashlib
import importlib.util
import json
from pathlib import Path
import re
import subprocess
import sys

# Each file below ships in the evaluator's serve image or is loaded/invoked by
# the runtime. Additional top-level .py files are discovered automatically.
FIXED_RUNTIME = {
    "harness.py","serve.py","taskbridge.py","task-tools.ts",
    "package.json","package-lock.json","requirements.txt","submission.yaml",
}
SHA_RE = re.compile(r"^(?:100644|100755|100664) ([0-9a-f]{40})$")


def blob_sha(contents: bytes) -> str:
    return hashlib.sha1(b"blob " + str(len(contents)).encode() + b"\0" + contents).hexdigest()


def _kit_python(kit_root: Path) -> str:
    if all(importlib.util.find_spec(m) is not None for m in ("yaml", "dotenv", "huggingface_hub")):
        return sys.executable
    for cand in (kit_root / ".venv" / "bin" / "python", Path("/tmp/ple-harness-venv/bin/python")):
        if cand.is_file():
            return str(cand)
    return sys.executable


def evaluate(root: Path) -> dict:
    source = root/"artifacts"/"manifest.json"
    try:
        manifest=json.loads(source.read_text(encoding="utf8"))
    except (OSError,UnicodeError,json.JSONDecodeError) as exc:
        raise ValueError(f"manifest inaccessible or malformed: {type(exc).__name__}") from exc
    harness=manifest.get("harness")
    if not isinstance(harness,dict) or not isinstance(harness.get("files"),dict):
        raise ValueError("artifacts/manifest.json lacks a harness.files source manifest")
    known=harness["files"]
    runtime=FIXED_RUNTIME | {p.name for p in root.glob("*.py") if p.is_file()}
    missing=[];diverged=[];unsafe=[];matching=[]
    for name in sorted(runtime):
        path=root/name
        if not path.is_file() or path.is_symlink():
            unsafe.append({"path":name,"reason":"missing_or_symlink_runtime_input"})
            continue
        expected=known.get(name)
        if expected is None:
            missing.append(name)
            continue
        m=SHA_RE.fullmatch(expected) if isinstance(expected,str) else None
        if not m:
            unsafe.append({"path":name,"reason":"malformed_recorded_git_blob"})
            continue
        actual=blob_sha(path.read_bytes())
        if actual!=m.group(1):
            diverged.append({"path":name,"expected":m.group(1),"current":actual})
        else:
            matching.append(name)
    # Manifest may retain paths that were deleted from current source. If the
    # artifact relied on those executable inputs, it is not reproducible.
    removed=[]
    for name in sorted(known):
        if name in runtime:
            continue
        if name.endswith((".py",".ts",".js",".json")) and not (root/name).exists():
            removed.append(name)
    tasks_map = manifest.get("tasks")
    empty_file_tasks = []
    if isinstance(tasks_map, dict):
        for tid, trec in sorted(tasks_map.items()):
            if isinstance(trec, dict) and not (trec.get("files") or {}):
                traj = root / "artifacts" / tid / "trajectory.json"
                if traj.is_file() and ".zip" in traj.read_text(encoding="utf8", errors="ignore").lower():
                    empty_file_tasks.append(tid)
    status="fresh" if not (missing or diverged or unsafe or removed or empty_file_tasks) else "stale"
    return {"schema":"hamon.ple.provenance.v1","status":status,
            "manifest_run_commit":harness.get("commit"),
            "manifest_harness_tree":harness.get("tree"),
            "source_files_checked":len(runtime),
            "matching":matching,
            "missing_in_manifest":missing,
            "diverged":diverged,
            "unsafe":unsafe,
            "removed_executable":removed,
            "empty_archive_tasks":empty_file_tasks,
            "note":"Fresh source hashes are necessary, not sufficient: dev-run provenance, organizer eligibility and real scores must be verified separately."}


def evaluate_official(root: Path, kit_root: Path) -> dict:
    """Run the organizer's working-tree review and qualify its provenance."""
    if not (kit_root / "kit" / "__main__.py").is_file():
        raise ValueError("organizer checkout lacks kit/__main__.py")
    if not (kit_root / "eval" / "dev_set.yaml").is_file():
        raise ValueError("organizer checkout lacks eval/dev_set.yaml")
    result = subprocess.run(
        [_kit_python(kit_root), "-m", "kit", "artifacts", "--json", str(root.resolve())],
        cwd=kit_root, text=True, capture_output=True, check=False,
    )
    try:
        report = json.loads(result.stdout)
    except json.JSONDecodeError as exc:
        raise ValueError(
            f"organizer kit produced no JSON review (exit {result.returncode}); "
            "run this checker with the organizer kit's Python environment"
        ) from exc
    if not isinstance(report, dict) or report.get("format") != 1:
        raise ValueError("unsupported organizer artifact review format")
    accepted = report.get("accepted")
    if not isinstance(accepted, bool) or result.returncode != (0 if accepted else 1):
        raise ValueError("organizer exit code and acceptance field disagree")
    if report.get("unreadable") is not False:
        raise ValueError("organizer could not review this entry")
    provenance = report.get("provenance")
    if not isinstance(provenance, dict):
        raise ValueError("organizer review lacks provenance")
    tasks = report.get("tasks")
    if not isinstance(tasks, list):
        raise ValueError("organizer review lacks task results")
    unrecorded = [
        task["id"] for task in tasks
        if task.get("status") == "ok" and "not in manifest.json" in task.get("warnings", [])
    ]
    empty_tasks = [task["id"] for task in tasks if task.get("status") == "empty"]
    missing_tasks = [task["id"] for task in tasks if task.get("status") in ("missing", "refused")]
    # The organizer explicitly accepts docs-only drift as the same runtime.
    # Require zero empty/missing/refused worlds for fresh certification.
    fresh = (accepted and provenance.get("manifest") == "ok"
             and provenance.get("dev_set") == "same"
             and provenance.get("harness") in ("same", "docs-only")
             and provenance.get("edited") == [] and not unrecorded
             and not empty_tasks and not missing_tasks)
    return {
        "schema": "hamon.ple.official-provenance.v1",
        "status": "fresh" if fresh else "stale",
        "kit_exit": result.returncode,
        "unrecorded_usable_tasks": unrecorded,
        "empty_tasks": empty_tasks,
        "missing_tasks": missing_tasks,
        "kit_review": report,
    }


def main(argv=None):
    ap=argparse.ArgumentParser(description=__doc__)
    ap.add_argument("submission_dir",type=Path)
    ap.add_argument("--kit-root", type=Path,
                    help="Run the public organizer kit to verify the full harness, dev-set and task exports.")
    args=ap.parse_args(argv)
    try:
        if args.kit_root is None:
            report=evaluate(args.submission_dir)
        else:
            report=evaluate_official(args.submission_dir, args.kit_root)
    except (OSError, ValueError) as exc:
        print(json.dumps({"schema":"hamon.ple.provenance.v1","status":"invalid",
                          "reason":str(exc)}))
        return 2
    print(json.dumps(report,indent=2,sort_keys=True))
    return 0 if report["status"]=="fresh" else 3


if __name__=="__main__":
    sys.exit(main())
